CREATE TABLE zc_jobs.trace_fixture(id integer); CREATE FUNCTION zc_jobs.trace_fixture_enqueue() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM zc_jobs.enqueue('bulk','refreshGlobalMetrics','{}','trigger-fixture',NULL,3); RETURN NEW; END $$; CREATE TRIGGER trace_fixture_enqueue AFTER INSERT ON zc_jobs.trace_fixture FOR EACH ROW EXECUTE FUNCTION zc_jobs.trace_fixture_enqueue(); INSERT INTO zc_jobs.trace_fixture VALUES(1)
